#!/usr/bin/env python3
"""Generate synchronized Days 211–224 exports from plan-source.json."""
from __future__ import annotations
import json, os, tempfile
from datetime import date, timedelta
from pathlib import Path

ROOT=Path(__file__).resolve().parents[1]
OUT=ROOT/"docs/reboot/continuation-211-224"
SOURCE=OUT/"plan-source.json"
def atomic_json(path:Path,value):
    path.parent.mkdir(parents=True,exist_ok=True)
    data=json.dumps(value,indent=2,ensure_ascii=False)+"\n"
    with tempfile.NamedTemporaryFile("w",encoding="utf-8",dir=path.parent,delete=False) as f:
        f.write(data); tmp=Path(f.name)
    try:
        json.loads(tmp.read_text(encoding="utf-8")); os.replace(tmp,path)
    finally:
        if tmp.exists(): tmp.unlink()
def generate():
    p=json.loads(SOURCE.read_text()); tasks=p["tasks"]
    assert len(tasks)==14
    cats=("project","ai","cert","ai_study","cert_study","core_study")
    assert {k:sum(t[k] for t in tasks) for k in cats}=={"project":1320,"ai":240,"cert":50,"ai_study":120,"cert_study":90,"core_study":280}
    assert sum(t["project"]+t["ai"]+t["cert"]+t["ai_study"]+t["cert_study"]+t["core_study"]+15 for t in tasks)==2310
    assert all(sum(t[k] for k in cats if k in ("project","ai","cert"))==115 and sum(t[k] for k in ("ai_study","cert_study","core_study"))==35 for t in tasks)
    dates=[date(2027,5,22)+timedelta(days=i) for i in range(14)]
    days=[]; cards=[]; notes=[]
    for i,(d,t) in enumerate(zip(dates,tasks)):
        n=211+i; question=p["question_bank"][t["question"]] if t["shared"]=="question" else None
        shared={"minutes":45,"within_engineering_minutes":False,"mode":"system_design_question_session" if question else "unfinished_review","question_id":question["id"] if question else None,"question_title":question["title"] if question else None,"review_task":None if question else f"Review {', '.join(t['files'])}; record first failing assertion or unresolved invariant and next selector; no capstone architecture proposal.","allocation_minutes":{"requirements":5,"constraints":5,"architecture_or_review":15,"failure_modes":10,"tradeoffs_and_next_step":10}}
        alloc={"project_implementation_tests":t["project"],"ai_workflow_implementation_evaluation":t["ai"],"certification_labs_questions":t["cert"],"ai_concept_source_study":t["ai_study"],"certification_domain_study":t["cert_study"],"core_systems_security_cloud_study":t["core_study"],"evidence":15}
        decision=f"{t['title']}: keep the complete bundle synthetic and local. First run `python3 scripts/check_continuation_211_entry_gate.py`. Only an actual learner-owned Day 210 boundary record can make ingestion eligible; Day 211 runs a gate-only check and does not ingest; absent/blocked status routes the project minutes to the exact CoverStory recovery selectors in this contract and the AI slice to fixed offline evaluator fixtures. If eligible, learner implements only `{t['seam']}` in {', '.join(t['files'])}; validate with `{t['selector']}`. Authorization filters owner and approved status before ranking; outputs cite immutable source/version IDs or abstain. No model, service, cloud resource or consequential decision."
        day={"day":n,"date":d.isoformat(),"title":t["title"],"learner_seam":t["seam"],"module":"CoverStory bounded synthetic workflow","signature":", ".join(t["files"]),"selectors":["python3 scripts/check_continuation_211_entry_gate.py",t["selector"]],"depends_on_days":[n-1] if i else [],"recovery_day":t["shared"]=="review","study_refs":[s["url"] for s in p["sources"]],"study_guidance":p["sources"],"engineering_architecture":{"decision":decision,"note_ref":f"assistant-architecture-notes.md#day-{n}","mode":"assistant_supplied_capstone_architecture; learner_implements_and_tests","capstone_proposal_required":False,"system_design_scope":"separate_interview_question_bank_only"},"budget":{"engineering_minutes":165,"study":35,"practice_and_tests":115,"evidence":15,"shared_interview_or_remaining_reviews_minutes":45,"total":210,"workstream_minutes":alloc},"workstream_minutes":alloc,"task_minutes":{"project_implementation_tests":f"{t['project']}m: implement/recover {t['seam']} in {', '.join(t['files'])}; run `{t['selector']}` and save actual output. If the Day 210 gate is absent/blocked, run the first unmet CoverStory selector from {', '.join(p['recovery_selectors'])}; do not attempt new ingestion. The Day 211 gate-only command inspects eligibility; it never ingests a bundle.","ai_workflow_implementation_evaluation":f"{t['ai']}m: {'extend fixed offline adversarial/evaluation cases for '+t['seam']+'; keep independent expected labels and no provider call' if t['ai'] else 'no AI implementation slice today; do not create extra work'}.","certification_labs_questions":f"{t['cert']}m: {'offline retrieval prompt on '+('SAA-C03 Exam content' if n%2 else 'Developer Associate currently linked exam guide')+'; record exact current version/title and checked answer, no readiness claim' if t['cert'] else 'no certification lab/question slice today; no paid exam or booking'}.","ai_concept_source_study":f"{t['ai_study']}m: study OpenAI Retrieval and the exact local seam; record one concept and limitation; no API use.","certification_domain_study":f"{t['cert_study']}m: inspect {('SAA-C03 Exam content' if n%2 else 'AWS Certified Developer - Associate / Review the exam guide')}; recheck exact published guide/version/heading; record one relevant concept; no readiness claim.","core_systems_security_cloud_study":f"{t['core_study']}m: study Python json Basic Usage, hashlib Hash algorithms, subprocess Using the subprocess Module, and AWS source comparison relevant to {t['seam']}; concepts only, no cloud calls.","evidence":f"15m: preserve actual status (not_attempted/not_run until learner acts), command/output, source SHA, artifact paths and digests, assistance, first unmet assertion and next action. CI/scaffold is not learner completion."},"shared_interview_block":shared,"learner_status":"unobserved_not_implied_by_scaffold","task":t,"separate_learning_repository":p["separate_learning_repository"]}
        days.append(day);cards.append({"day_number":n,"date":d.isoformat(),"title":t["title"],"learner_seam":t["seam"],"signature":day["signature"],"selectors":day["selectors"],"prerequisite_days":day["depends_on_days"],"recovery_day":day["recovery_day"],"engineering":{"minutes":165,"allocation":alloc},"budget_minutes":{"engineering":165,"shared_interview_or_remaining_reviews":45,"total":210},"study_guidance":day["study_guidance"],"shared_interview_block":shared,"status":"unobserved_not_implied_by_scaffold","separate_learning_repository":p["separate_learning_repository"]})
        notes.append(f"<a id=\"day-{n}\"></a>\n## Day {n} — {t['title']}\n\n**What:** {decision}\n\n**Why:** Keep source authorization, immutable provenance and local evaluation observable at this seam; a failing prerequisite selects recovery and cannot be inferred from scaffold CI.\n")
    manifest={"title":p["title"],"status":"starter_not_learner_completion_or_board_published","branch":p["branch"],"base_commit":p["base_commit"],"engineering_minutes":165,"engineering_allocation":p["allocation_minutes"],"engineering_minutes_total":2310,"shared_interview_or_remaining_reviews_minutes":45,"total_daily_minutes":210,"scope":p["scope"],"gate_policy":p["gate"],"source_keys":[s["key"] for s in p["sources"]],"days":days,"separate_learning_repository":p["separate_learning_repository"]}
    transfer={"title":p["title"],"status":manifest["status"],"branch":p["branch"],"source":{"base_commit":p["base_commit"],"runtime":"Python standard library; offline only"},"dates":{"start":p["start_date"],"end":p["end_date"],"recovery_days":[d["day"] for d in days if d["recovery_day"]]},"budget":{"engineering_minutes":165,"allocation":{"study":35,"practice_and_tests":115,"evidence":15},"shared_interview_or_remaining_reviews_minutes":45,"total":210,"window_workstreams":p["allocation_minutes"]},"gate_policy":p["gate"],"recovery_selectors":p["recovery_selectors"],"days":days}
    owner={"title":p["title"],"status":manifest["status"],"branch":p["branch"],"base_commit":p["base_commit"],"board_writes":False,"story_count":14,"cards":cards,"separate_learning_repository":p["separate_learning_repository"]}
    for name,obj in [("manifest.json",manifest),("days-211-224-transfer-plan.json",transfer),("scrum-owner-manifest.json",owner)]:atomic_json(OUT/name,obj)
    for d in days:
        n=d['day']; t=d['task']; dsa=p['separate_learning_repository']['algorithm_practice']; shared=d['shared_interview_block']; src_lines='; '.join(x['title']+' — '+', '.join(x['sections'])+' ('+x['url']+')' for x in d['study_guidance']); lines=[f"<a id=\"day-{n}\"></a>",f"# Day {n}: {t['title']}","",f"Date: {d['date']}","",f"**Assistant-supplied architecture — what and why:** {d['engineering_architecture']['decision']}","",f"**Named work:** {d['task_minutes']['project_implementation_tests']}","",f"**Acceptance command:** `{t['selector']}`","",f"**Engineering budget (165m):** project/tests {t['project']}m; AI workflow/evaluation {t['ai']}m; certification practice {t['cert']}m; AI concept study {t['ai_study']}m; certification study {t['cert_study']}m; core systems/security/cloud study {t['core_study']}m; evidence 15m.","",f"**Study references:** {src_lines}","",f"**Shared 45-minute block:** {shared['mode']} — {(shared['question_id']+' — '+shared['question_title']) if shared['question_id'] else shared['review_task']}; requirements 5m, constraints 5m, design/review 15m, failures 10m, trade-offs and next step 10m.","",f"**Recovery:** if the entry gate is absent or blocked, use a named selector from [`README.md`](../README.md#entry-gate-and-recovery). DSA stays external in [{dsa}]({dsa}).",""]
        (OUT/f"contracts/day-{n}.md").write_text("\n".join(lines),encoding="utf-8")
    (OUT/"assistant-architecture-notes.md").write_text("# Assistant-supplied architecture notes\n\nLearner implements and tests the supplied choices; no mandatory capstone proposal or post-hoc architecture defense.\n\n"+"\n".join(notes),encoding="utf-8")
    return manifest
if __name__=="__main__":
    m=generate();print(f"generated {len(m['days'])} days; engineering={m['engineering_minutes_total']} min")
